import heapq


class TaskScheduler:
    def __init__(self):
        self.heap = []
        self.counter = 0

    def add(self, name, priority):
        heapq.heappush(self.heap, (priority, self.counter, name))
        self.counter += 1

    def next_task(self):
        if not self.heap:
            return None
        return heapq.heappop(self.heap)[2]

    def size(self):
        return len(self.heap)

